printChar MACRO char
    mov AH,02h
    mov DL,char
    int 21h
ENDM

.MODEL
.STACK
.DATA
    COND db 10d
    COND2 db 10B
.CODE
    ;description
    main PROC
        mov DX,@data
        mov DS,DX
        xor DX,DX

        cmp COND,1B
        je L1
        jmp L2

        L1:
            printChar 'a'
            jmp L3

        L2:
            printChar 'b'
            jmp L1

        L3:

        .EXIT
    main ENDP

end main